def transform(grid):
    g=[r[:] for r in grid]
    H,W=len(g),len(g[0])
    # The solid seed shapes are periodic tiles; repeat each seed across its own zero canvas.
    colors={v for row in grid for v in row if v not in (0,8)}
    for color in colors:
        pts=[(r,c) for r in range(H) for c in range(W) if grid[r][c]==color]
        r0,r1=min(r for r,c in pts),max(r for r,c in pts)
        c0,c1=min(c for r,c in pts),max(c for r,c in pts)
        # Use bounding-box motif, including zero-valued cells, and tile anchored to the seed.
        h,w=r1-r0+1,c1-c0+1
        motif=[[grid[r0+i][c0+j] for j in range(w)] for i in range(h)]
        # canvas is contiguous region of 0/color cells containing seed
        cells={(r,c) for r in range(H) for c in range(W) if grid[r][c] in (0,color)}
        todo=[(r0,c0)]; component={(r0,c0)}
        while todo:
            r,c=todo.pop()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(r+dr,c+dc)
                if p in cells and p not in component: component.add(p); todo.append(p)
        for r,c in component:
            g[r][c]=motif[(r-r0)%h][(c-c0)%w]
    return g
PY
